//go:build transcodechaos

package plex

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/braedonsaunders/ether/internal/config"
	"github.com/braedonsaunders/ether/internal/mediaproc"
	"github.com/braedonsaunders/ether/internal/transcode"
)

// The corpus is generated by cmd/transcodechaos -corpus; .good provides
// the source facts and .media is what the encoder actually reads.
func TestTranscodeChaosMatrix(t *testing.T) {
	corpus, ff, fp := os.Getenv("CHAOS_CORPUS"), os.Getenv("CHAOS_FFMPEG"), os.Getenv("CHAOS_FFPROBE")
	if corpus == "" {
		t.Skip("set CHAOS_CORPUS to run the generated input matrix")
	}
	if ff == "" || fp == "" {
		t.Fatal("set CHAOS_FFMPEG and CHAOS_FFPROBE")
	}
	entries, err := filepath.Glob(filepath.Join(corpus, "*.good"))
	if err != nil || len(entries) == 0 {
		t.Fatal("corpus has no input fixtures")
	}
	source := httptest.NewServer(http.FileServer(http.Dir(corpus)))
	defer source.Close()
	var logs io.Writer = io.Discard
	if os.Getenv("CHAOS_DEBUG") != "" {
		logs = os.Stderr
	}
	hw := os.Getenv("CHAOS_HW")
	if hw == "" {
		hw = "none"
	}
	m, err := transcode.New(config.Transcode{FFmpegPath: ff, FFprobePath: fp, HWAccel: hw, TempDir: filepath.Join(t.TempDir(), "work")}, slog.New(slog.NewTextHandler(logs, nil)), transcode.WithSegmentTimeout(10*time.Second))
	if err != nil {
		t.Fatal(err)
	}
	defer m.Close()
	if hw != "none" && m.HWAccel().Name != hw {
		t.Skip("requested hardware encoder unavailable")
	}
	check := func(t *testing.T, b []byte, ext string, damaged bool) {
		t.Helper()
		if len(b) == 0 {
			t.Fatal("empty output")
		}
		p := filepath.Join(t.TempDir(), "media."+ext)
		if e := os.WriteFile(p, b, 0600); e != nil {
			t.Fatal(e)
		}
		if output := os.Getenv("CHAOS_CAPTURE"); output != "" {
			if e := os.WriteFile(output, b, 0600); e != nil {
				t.Fatal(e)
			}
		}
		chaosCmd(t, fp, "-v", "error", "-show_streams", p)
		chaosDecodeMedia(t, ff, fp, p, damaged)
	}
	checkAudio := func(t *testing.T, b []byte, ext string) {
		t.Helper()
		p := filepath.Join(t.TempDir(), "audio."+ext)
		if err := os.WriteFile(p, b, 0600); err != nil {
			t.Fatal(err)
		}
		packets, err := mediaproc.CommandContext(context.Background(), 2*time.Minute, fp, "-v", "error", "-select_streams", "a:0", "-show_entries", "packet=pts_time", "-of", "csv=p=0", p).Output()
		if err != nil || len(strings.TrimSpace(string(packets))) == 0 {
			t.Fatal("seeked output has no audio packets")
		}
	}
	for _, entry := range entries {
		name := strings.TrimSuffix(filepath.Base(entry), ".good")
		t.Run(name, func(t *testing.T) {
			info, err := m.Probe(context.Background(), source.URL+"/"+name+".good")
			if err != nil {
				t.Fatalf("probe: %v", err)
			}
			info.Keyframes = nil
			if name == "input-multi-audio" {
				found := false
				for _, stream := range info.Streams {
					if stream.Type == "audio" && stream.Channels == 6 && stream.AACProgramConfig {
						found = true
					}
				}
				if !found {
					t.Fatal("probe did not identify the AAC program configuration")
				}
			}
			for _, path := range []string{"hls", "hls-fmp4", "dash", "start-mkv", "download"} {
				t.Run(path, func(t *testing.T) {
					if path == "download" && name == "input-hevc10-hdr" {
						t.Skip("HDR source is not an eligible copy-only download")
					}
					inputURL := source.URL + "/" + name + ".media"
					if path == "download" {
						f := newDownloadFixture(t, true)
						f.playback.info = *info
						f.srv.setPlayback(&chaosPlayback{f.playback, inputURL})
						dl, e := m.NewDownloadRemuxer(config.Downloads{})
						if e != nil {
							t.Fatal(e)
						}
						f.srv.sessionRuntime().SetDownloads(dl)
						q := f.queue(t)
						r := f.do(t, http.MethodPost, "/downloadQueue/"+itoa(q)+"/add?keys=/library/metadata/"+fightClub.Key.String(), ownerToken, nil)
						if r.Code != 200 {
							t.Fatalf("add HTTP %d", r.Code)
						}
						deadline := time.Now().Add(8 * time.Second)
						var item map[string]any
						for time.Now().Before(deadline) {
							items := f.items(t, q)
							if len(items) == 1 {
								item = items[0]
								if item["status"] == downloadAvailable {
									break
								}
								if item["status"] == downloadError {
									t.Fatalf("download conversion failed")
								}
							}
							time.Sleep(50 * time.Millisecond)
						}
						if item == nil || item["status"] != downloadAvailable {
							t.Fatal("download timed out")
						}
						id := int64(item["id"].(float64))
						r = f.do(t, http.MethodGet, "/downloadQueue/"+itoa(q)+"/item/"+itoa(id)+"/media", ownerToken, nil)
						if r.Code != 200 {
							t.Fatalf("media HTTP %d", r.Code)
						}
						check(t, r.Body.Bytes(), "mp4", strings.HasPrefix(name, "input-corrupt-"))
						f.do(t, http.MethodDelete, "/downloadQueue/"+itoa(q)+"/items/"+itoa(id), ownerToken, nil)
						return
					}
					f := newFixture()
					defer f.srv.Close()
					f.playback.info = *info
					f.srv.setPlayback(&chaosPlayback{f.playback, inputURL})
					recorder := &chaosTranscoderRecorder{Transcoder: m}
					f.srv.setTranscoder(recorder)
					id := "matrix-" + path
					query := "path=%2Flibrary%2Fmetadata%2F" + fightClub.Key.String() + "&session=" + id + "&directPlay=0&directStream=1"
					if strings.Contains(name, "subtitle") || strings.Contains(name, "broken-") {
						for _, st := range info.Streams {
							if st.Type == "subtitle" {
								track := f.bindStream(fightClub.Key, st.Index, st)
								query += fmt.Sprintf("&subtitles=burn&subtitleStreamID=%d", track)
								break
							}
						}
					}
					get := func(p string) []byte {
						t.Helper()
						headers := []string{"X-Plex-Product", "Plex Web", "X-Plex-Platform", "Chrome"}
						if path == "hls-fmp4" {
							headers = append(headers, "X-Plex-Client-Profile-Extra", "add-transcode-target(type=videoProfile&context=streaming&protocol=hls&container=mp4&videoCodec=h264,hevc&audioCodec=aac)")
						}
						r := f.get(t, p, headers...)
						if r.Code != 200 {
							t.Fatalf("HTTP %d for %s", r.Code, p)
						}
						return r.Body.Bytes()
					}
					defer func() {
						f.get(t, "/video/:/transcode/universal/stop?session="+id, "X-Plex-Product", "Plex Web", "X-Plex-Platform", "Chrome")
					}()
					// Official clients ask for a decision first; start requires
					// that armed decision, and a refusal carries the reason.
					protocol := map[string]string{"dash": "dash", "start-mkv": "http"}[path]
					if protocol == "" {
						protocol = "hls"
					}
					decision := string(get("/video/:/transcode/universal/decision?" + query + "&protocol=" + protocol))
					if !strings.Contains(decision, `transcodeDecisionCode="1001"`) {
						t.Fatalf("conversion refused: %s", decision)
					}
					switch path {
					case "hls":
						get("/video/:/transcode/universal/start.m3u8?" + query + "&protocol=hls")
						if name == "input-multi-audio" && (len(recorder.requests) == 0 || recorder.requests[len(recorder.requests)-1].Decision.AudioCopy) {
							t.Fatal("PCE AAC was incorrectly advertised as copied")
						}
						ext, outputExt := "ts", "ts"
						var init []byte
						if len(recorder.requests) > 0 && recorder.requests[len(recorder.requests)-1].Decision.Container == "fmp4" {
							ext, outputExt = "m4s", "mp4"
							init = get("/video/:/transcode/universal/session/" + id + "/base/init.mp4")
						}
						for n := 0; n < 3 && (info.Duration <= 0 || time.Duration(n)*4*time.Second < info.Duration); n++ {
							media := get(fmt.Sprintf("/video/:/transcode/universal/session/%s/base/%05d.%s", id, n, ext))
							check(t, append(append([]byte(nil), init...), media...), outputExt, strings.HasPrefix(name, "input-corrupt-"))
						}
						if name == "input-corrupt-mp4" {
							session, ok := m.Session(id)
							if !ok || session.(*transcode.Session).Decision().VideoCopy {
								t.Fatal("fatal copy conversion did not switch to video encoding")
							}
							w := httptest.NewRecorder()
							session.ServePlaylist(w, httptest.NewRequest(http.MethodGet, "/playlist", nil))
							if !strings.Contains(w.Body.String(), "#EXT-X-DISCONTINUITY\n") {
								t.Fatal("copy recovery did not advertise the parameter change")
							}
						}
						if name == "input-multi-audio" {
							seekID := id + "-seek"
							seekQuery := strings.Replace(query, "session="+id, "session="+seekID, 1)
							get("/video/:/transcode/universal/start.m3u8?" + seekQuery + "&protocol=hls&offset=6")
							media := get("/video/:/transcode/universal/session/" + seekID + "/base/00000.ts")
							check(t, media, "ts", false)
							checkAudio(t, media, "ts")
							get("/video/:/transcode/universal/stop?session=" + seekID)
						}
					case "hls-fmp4":
						get("/video/:/transcode/universal/start.m3u8?" + query + "&protocol=hls")
						if len(recorder.requests) == 0 || recorder.requests[len(recorder.requests)-1].Decision.Container != "fmp4" {
							t.Fatal("client did not negotiate fMP4 HLS")
						}
						base := "/video/:/transcode/universal/session/" + id + "/base/"
						init := get(base + "init.mp4")
						for n := 0; n < 3 && (info.Duration <= 0 || time.Duration(n)*4*time.Second < info.Duration); n++ {
							media := get(fmt.Sprintf("%s%05d.m4s", base, n))
							check(t, append(append([]byte(nil), init...), media...), "mp4", strings.HasPrefix(name, "input-corrupt-"))
						}
						if name == "input-multi-audio" {
							seekID := id + "-seek"
							seekQuery := strings.Replace(query, "session="+id, "session="+seekID, 1)
							get("/video/:/transcode/universal/start.m3u8?" + seekQuery + "&protocol=hls&offset=6")
							seekBase := "/video/:/transcode/universal/session/" + seekID + "/base/"
							seekInit := get(seekBase + "init.mp4")
							media := get(seekBase + "00000.m4s")
							joined := append(seekInit, media...)
							check(t, joined, "mp4", false)
							checkAudio(t, joined, "mp4")
							get("/video/:/transcode/universal/stop?session=" + seekID)
						}
					case "dash":
						get("/video/:/transcode/universal/start.mpd?" + query + "&protocol=dash")
						base := "/video/:/transcode/universal/session/" + id + "/0/"
						init := get(base + "header")
						for n := 0; n < 2 && (info.Duration <= 0 || time.Duration(n)*5*time.Second < info.Duration); n++ {
							media := get(fmt.Sprintf("%s%d.m4s", base, n))
							check(t, append(append([]byte(nil), init...), media...), "mp4", strings.HasPrefix(name, "input-corrupt-"))
						}
					case "start-mkv":
						check(t, get("/video/:/transcode/universal/start.mkv?"+query+"&protocol=http"), "mkv", strings.HasPrefix(name, "input-corrupt-"))
					}
				})
			}
		})
	}
}
